fn shift_in(c: String, k: Int, alphabet: String) -> Option[String] {
  let letters = split(alphabet, "")
  let hits = filter(enumerate(letters), |p| p.1 == c)
  return match first(hits) {
    Some(p) => first(drop(letters, ((p.0 + k) % 26 + 26) % 26)),
    None => None,
  }
}

fn shift_char(c: String, k: Int) -> String {
  return match shift_in(c, k, "abcdefghijklmnopqrstuvwxyz") {
    Some(x) => x,
    None => unwrap_or(shift_in(c, k, "ABCDEFGHIJKLMNOPQRSTUVWXYZ"), c),
  }
}

fn caesar_shift(s: String, k: Int) -> String {
  return s
    |> split("")
    |> map(|c| shift_char(c, k))
    |> join("")
}

