from collections import Counter


def k_most_frequent(xs: list[int], k: int) -> list[tuple[int, int]]:
    """Return the k most frequent (value, count) pairs, by count desc then first occurrence in xs."""
    if k <= 0:
        return []
    counts: Counter[int] = Counter(xs)
    first_index: dict[int, int] = {}
    for i, x in enumerate(xs):
        if x not in first_index:
            first_index[x] = i
    ranked = sorted(counts.items(), key=lambda pair: (-pair[1], first_index[pair[0]]))
    return ranked[:k]

