  let inner_cs = take(drop(cs, 1), len(cs) - 2)
  if unwrap_or(first(inner_cs), "") == "-" {
    return Err("missing $")
  }
  let v = try parse_plain(join(inner_cs, ""))
  return Ok(0 - v)
}

