  let out = "";
  for (const c of s) {
    if (c >= "a" && c <= "z") {
      const i = (((c.charCodeAt(0) - 97 + k) % 26) + 26) % 26;
      out += String.fromCharCode(97 + i);
    } else if (c >= "A" && c <= "Z") {
      const i = (((c.charCodeAt(0) - 65 + k) % 26) + 26) % 26;
      out += String.fromCharCode(65 + i);
    } else {
      out += c;
    }
  }
  return out;
}

