    """Parse a duration such as "2d1h30m15s" into seconds."""
    if not s:
        return {"ok": False, "error": "empty"}
    total = 0
    digits = ""
    last_rank = -1
    for ch in s:
        if ch in _DIGITS:
            digits += ch
