def text_editor(ops: list[EditOp]) -> str:
    """Apply editing operations to an initially empty line and return the final text."""
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []
    redo_history: list[tuple[str, int]] = []
    for op in ops:
