            redo_history.clear()
            text = text[:cursor] + op["text"] + text[cursor:]
            cursor += len(op["text"])
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            redo_history.clear()
            removed = min(op["n"], cursor)
            text = text[: cursor - removed] + text[cursor:]
            cursor -= removed
        elif op["kind"] == "Left":
            cursor = max(cursor - op["n"], 0)
        elif op["kind"] == "Right":
            cursor = min(cursor + op["n"], len(text))
        elif op["kind"] == "Undo":
            if history:
                redo_history.append((text, cursor))
                text, cursor = history.pop()
        else:
            if redo_history:
                history.append((text, cursor))
                text, cursor = redo_history.pop()
    return text

